package com.suarez.empleados; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController public class ConfiguracionController { @Value("${empresa.ambiente}") String ambiente; @Value("${spring.profiles.active:dev}") String perfil; @Value("${server.port}") String puerto; @Value("${spring.datasource.url}") String url; @GetMapping("/configuracion") public Map<String,String> config(){var db=url.substring(url.lastIndexOf('/')+1);return Map.of("ambiente",ambiente,"perfil",perfil,"puerto",puerto,"baseDatos",db);} }
